customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
@media(min-width:961px){.kpis{grid-template-columns:1.7fr 1fr 1fr;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=max>0?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
async function main(){
var root=document.getElementById('app');
var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
var rows=await recs(500);
var tMap=optionMap(ctx.fields,'customer_type');
var tC=countBy(rows,'customer_type');
var now=new Date(),moN=0;
for(var i=0;i<rows.length;i++){var d0=pd(rows[i].submittedAt);if(d0&&d0.getMonth()===now.getMonth()&&d0.getFullYear()===now.getFullYear())moN++;}
var bizN=rows.length-(tC['residential']||0);
var heroSub=rows.length?'<b>'+fmtInt(tC['residential']||0)+'</b> residential \u00b7 <b>'+fmtInt(bizN)+'</b> business':'Add your first customer to get started';
var bd=breakdown(rows,'customer_type',tMap)||emptyBlock(I.chart,'The customer mix appears once customers are added.','+ New customer');
var recent='';
for(var r=0;r<rows.length&&r<6;r++){var a=rows[r].answers||{};var right=a.phone?'<span class="chip">'+h(a.phone)+'</span>':'';recent+=rowItem(h(a.name||'Customer'),h(labelFor(tMap,a.customer_type))+' \u00b7 '+h(fmtDate(rows[r].submittedAt)),right);}
if(!recent)recent=emptyBlock(I.user,'New customers land here as they are added.','+ New customer');
var html='<div class="wrap">';
html+=headerBlock(I.user,ctx.title||'Customers',brief(['<b>'+fmtInt(rows.length)+'</b> customers on the books','<b>'+fmtInt(moN)+'</b> added this month',bizN>0?'<b>'+fmtInt(bizN)+'</b> business accounts':'']),'New customer');
html+='<div class="kpis">'+kpi('Customers',rows.length,heroSub,{hero:true,spark:spark(weekly(rows))})+kpi('New this month',moN,moN>0?'Added since the 1st':'No new customers yet this month')+kpi('Business accounts',bizN,'Commercial, strata, agencies & PMs')+'</div>';
html+=sec('Customer book')+'<div class="grid g21">'+panel('Customers by type',bd)+panel('Recent customers','<div class="rows">'+recent+'</div>')+'</div>';
html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
@media(min-width:961px){.kpis{grid-template-columns:1.7fr 1fr 1fr;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=max>0?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var gWrench=icoSvg('<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>');
function stKind(s){return s==='completed'||s==='invoiced'?'good':s==='on-hold'?'warn':s==='in-progress'?'accent':'neutral';}
function dayLabel(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}):'Upcoming';}
async function main(){
var root=document.getElementById('app');
var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
var rows=await recs(500);
var stMap=optionMap(ctx.fields,'status'),tyMap=optionMap(ctx.fields,'job_type'),prMap=optionMap(ctx.fields,'priority');
var stC=countBy(rows,'status');
var openN=(stC['scheduled']||0)+(stC['in-progress']||0)+(stC['on-hold']||0);
var weekN=0,todayN=0,emergN=0;
for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};var dd=dayDiff(a.scheduled_date);var op=a.status==='scheduled'||a.status==='in-progress'||a.status==='on-hold';if(op&&dd!=null&&dd>=0&&dd<=7)weekN++;if(op&&dd===0)todayN++;if(a.job_type==='emergency'&&op)emergN++;}
var up=[];
for(var u=0;u<rows.length;u++){var ua=rows[u].answers||{};var d2=dayDiff(ua.scheduled_date);if(d2!=null&&d2>=0&&(ua.status==='scheduled'||ua.status==='in-progress'))up.push(rows[u]);}
up.sort(function(x,y){return String((x.answers||{}).scheduled_date||'').localeCompare(String((y.answers||{}).scheduled_date||''));});
var schedule='',lastKey='';
for(var b=0;b<up.length&&b<8;b++){var ba=up[b].answers||{};var d3=dayDiff(ba.scheduled_date);var key=d3===0?'Today':d3===1?'Tomorrow':dayLabel(ba.scheduled_date);if(key!==lastKey){if(lastKey!=='')schedule+='</div>';schedule+='<div class="day"><div class="day-h">'+h(key)+'</div>';lastKey=key;}var subj=h(labelFor(tyMap,ba.job_type))+(ba.priority?' '+pill(labelFor(prMap,ba.priority),ba.priority==='urgent'?'bad':ba.priority==='high'?'warn':'neutral'):'');schedule+='<div class="sch"><div class="row-main"><div class="row-title">'+h(ba.site_address||'Job')+'</div><div class="row-sub">'+subj+'</div></div><div class="row-r">'+pill(labelFor(stMap,ba.status),stKind(ba.status))+'</div></div>';}
if(lastKey!=='')schedule+='</div>';
if(!schedule)schedule=emptyBlock(I.cal,'Booked jobs appear here by day, ready to dispatch.','+ New job');
var bd=breakdown(rows,'status',stMap)||emptyBlock(I.chart,'The status mix appears once jobs are booked.','+ New job');
var recent='';
for(var r2=0;r2<rows.length&&r2<5;r2++){var ra=rows[r2].answers||{};var ev=num(ra.estimated_value);var rt=(ev>0?'<span class="amt">'+mnyC(ev)+'</span>':'')+pill(labelFor(stMap,ra.status),stKind(ra.status));recent+=rowItem(h(ra.site_address||'Job'),h(labelFor(tyMap,ra.job_type))+' \u00b7 '+h(fmtDate(ra.scheduled_date||rows[r2].submittedAt)),rt);}
if(!recent)recent=emptyBlock(gWrench,'New jobs land here as they are booked.','+ New job');
var heroSub=rows.length?'<b>'+fmtInt(stC['scheduled']||0)+'</b> scheduled \u00b7 <b>'+fmtInt(stC['in-progress']||0)+'</b> in progress \u00b7 <b>'+fmtInt(stC['on-hold']||0)+'</b> on hold':'Book your first job to fill the board';
var html='<div class="wrap">';
html+=headerBlock(gWrench,ctx.title||'Jobs',brief(['<b>'+fmtInt(openN)+'</b> open jobs','<b>'+fmtInt(weekN)+'</b> on the board this week',emergN>0?'<b>'+fmtInt(emergN)+'</b> emergency call-outs':'']),'New job');
html+='<div class="kpis">'+kpi('Open jobs',rows.length?openN:'\u2014',heroSub,{hero:true,spark:spark(weekly(rows))})+kpi('This week',weekN,todayN>0?'<b>'+fmtInt(todayN)+'</b> on site today':'Booked over the next 7 days')+kpi('Emergency',emergN,emergN>0?'<span style="color:var(--fl-bad);font-weight:650">Respond to these first</span>':'No emergency call-outs open')+'</div>';
html+=sec('Job board')+'<div class="grid g21">'+panel('Today & upcoming',schedule)+'<div class="grid">'+panel('Jobs by status',bd)+panel('Recent jobs','<div class="rows">'+recent+'</div>')+'</div></div>';
html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
@media(min-width:961px){.kpis{grid-template-columns:1.7fr 1fr 1fr;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=max>0?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var gClip=icoSvg('<path d="M9 4H7a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-2"/><rect x="9" y="2.5" width="6" height="3" rx="1"/><path d="M9 12.5l2 2 4-4"/>');
function fu(a){var v=a.follow_up_required;return Array.isArray(v)?v.length>0:!!v;}
async function main(){
var root=document.getElementById('app');
var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
var rows=await recs(500);
var hrs=sumBy(rows,'hours_on_site');
var fuN=0;for(var i=0;i<rows.length;i++){if(fu(rows[i].answers||{}))fuN++;}
var bd=breakdown(rows,'technician_name',{})||emptyBlock(I.chart,'Visits split by technician appear here.','+ Log a site visit');
var recent='';
for(var r=0;r<rows.length&&r<6;r++){var a=rows[r].answers||{};var work=String(a.work_performed||'');var sub=h(fmtDate(a.visit_date||rows[r].submittedAt))+(work?' \u00b7 '+h(work):'');var right='<span class="chip">'+h(fmtInt(num(a.hours_on_site)))+'h</span>'+(fu(a)?pill('Follow-up','warn'):'');recent+=rowItem(h(a.technician_name||'Site visit'),sub,right);}
if(!recent)recent=emptyBlock(gClip,'Logged work orders and site visits appear here.','+ Log a site visit');
var html='<div class="wrap">';
html+=headerBlock(gClip,ctx.title||'Site Visits',brief(['<b>'+fmtInt(rows.length)+'</b> visits logged','<b>'+fmtInt(hrs)+'</b> hours on site',fuN>0?'<b>'+fmtInt(fuN)+'</b> need a follow-up':'']),'Log site visit');
html+='<div class="kpis">'+kpi('Site visits',rows.length,rows.length?'Work orders logged by the crew':'Log the first visit from the field',{hero:true,spark:spark(weekly(rows))})+kpi('Hours on site',fmtInt(hrs),rows.length?'Across all logged visits':'Time on the tools shows here')+kpi('Follow-ups',fuN,fuN>0?'<span style="color:var(--fl-warn);font-weight:650">Book the return visits</span>':'Nothing waiting on a return visit')+'</div>';
html+=sec('Field log')+'<div class="grid g21">'+panel('Visits by technician',bd)+panel('Recent visits','<div class="rows">'+recent+'</div>')+'</div>';
html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
@media(min-width:961px){.kpis{grid-template-columns:1.7fr 1fr 1fr;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=max>0?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var gRcpt=icoSvg('<path d="M6 3h12v18l-2-1.5-2 1.5-2-1.5L10 21l-2-1.5L6 21z"/><path d="M9.5 8.5h5M9.5 12.5h5"/>');
function ivKind(s){return s==='paid'?'good':s==='overdue'?'bad':s==='sent'?'accent':'neutral';}
async function main(){
var root=document.getElementById('app');
var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
var rows=await recs(500);
var stMap=optionMap(ctx.fields,'status');
var total=sumBy(rows,'total');
var outst=0,unpaidN=0,overdueN=0,paid=0;
for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};if(a.status==='sent'||a.status==='overdue'){outst+=num(a.total);unpaidN++;if(a.status==='overdue')overdueN++;}if(a.status==='paid')paid+=num(a.total);}
var recent='';
for(var r=0;r<rows.length&&r<6;r++){var a2=rows[r].answers||{};recent+=rowItem(h(a2.invoice_number||'Invoice'),'Issued '+h(fmtDate(a2.issue_date||rows[r].submittedAt)),'<span class="amt">'+mny(a2.total)+'</span>'+pill(labelFor(stMap,a2.status),ivKind(a2.status)));}
if(!recent)recent=emptyBlock(gRcpt,'Raised invoices land here with their amounts.','+ New invoice');
var bd=breakdown(rows,'status',stMap)||emptyBlock(I.chart,'The status mix appears once invoices are raised.','+ New invoice');
var heroSub=rows.length?'<b>'+fmtInt(rows.length)+'</b> invoices \u00b7 <b>'+mnyC(paid)+'</b> collected':'Raise your first invoice from a completed job';
var html='<div class="wrap">';
html+=headerBlock(gRcpt,ctx.title||'Invoices',brief(['<b>'+mnyC(total)+'</b> invoiced','<b>'+mnyC(outst)+'</b> outstanding',overdueN>0?'<b>'+fmtInt(overdueN)+'</b> overdue':'']),'New invoice');
html+='<div class="kpis">'+kpi('Invoiced',rows.length?mnyC(total):'\u2014',heroSub,{hero:true,spark:spark(weekly(rows))})+kpi('Outstanding',mnyC(outst),unpaidN>0?'<b>'+fmtInt(unpaidN)+'</b> awaiting payment':'All invoices settled')+kpi('Overdue',overdueN,overdueN>0?'<span style="color:var(--fl-bad);font-weight:650">Chase these payments</span>':'Nothing past its due date')+'</div>';
html+=sec('Ledger')+'<div class="grid g21">'+panel('Recent invoices','<div class="rows">'+recent+'</div>')+panel('Invoices by status',bd)+'</div>';
html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
@media(min-width:961px){.kpis{grid-template-columns:1.7fr 1fr 1fr;}}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function optionMap(fields,fieldId){var m={};for(var i=0;i<(fields||[]).length;i++){var f=fields[i];if(f.id===fieldId&&f.options){for(var j=0;j<f.options.length;j++){m[f.options[j].value]=f.options[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(limit){try{return await FL.records({limit:limit||500});}catch(e){return [];}}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body){return '<div class="panel">'+(title?'<div class="panel-h"><button class="panel-t" data-records="1" style="background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;color:inherit">'+h(title)+'</button><button class="panel-link" data-records="1">View all</button></div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=max>0?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,cta){return '<div class="empty">'+(ic||'')+h(msg)+(cta?'<div><button class="link-btn" data-open="1">'+h(cta)+'</button></div>':'')+'</div>';}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,newLabel){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(newLabel){out+='<div class="hdr-r"><button class="btn btn-primary" data-open="1">'+I.plus+'<span>'+h(newLabel)+'</span></button></div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var opens=root.querySelectorAll('[data-open]');for(var i=0;i<opens.length;i++){(function(el){el.addEventListener('click',function(){FL.openForm().catch(function(){});});})(opens[i]);}var rls=root.querySelectorAll('[data-records]');for(var r0=0;r0<rls.length;r0++){(function(el){el.addEventListener('click',function(){FL.openRecords().catch(function(){});});})(rls[r0]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
function pKind(s){return s==='received'?'good':s==='ordered'?'accent':s==='requested'?'warn':'neutral';}
async function main(){
var root=document.getElementById('app');
var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this section.');}
var rows=await recs(500);
var stMap=optionMap(ctx.fields,'status');
var reqN=0,ordN=0,costT=0;
for(var i=0;i<rows.length;i++){var a=rows[i].answers||{};if(a.status==='requested')reqN++;if(a.status==='ordered')ordN++;costT+=(num(a.quantity)||1)*num(a.unit_cost);}
var recent='';
for(var r=0;r<rows.length&&r<6;r++){var a2=rows[r].answers||{};var q=num(a2.quantity)||1;var line=q*num(a2.unit_cost);var right=(line>0?'<span class="amt">'+mny(line)+'</span>':'<span class="chip">\u00d7'+fmtInt(q)+'</span>')+pill(labelFor(stMap,a2.status),pKind(a2.status));recent+=rowItem(h(a2.item||'Part'),'\u00d7'+fmtInt(q)+(a2.supplier?' \u00b7 '+h(a2.supplier):'')+' \u00b7 '+h(fmtDate(rows[r].submittedAt)),right);}
if(!recent)recent=emptyBlock(I.box,'Parts and materials requests land here.','+ New parts request');
var bd=breakdown(rows,'status',stMap)||emptyBlock(I.chart,'The status mix appears once parts are requested.','+ New parts request');
var heroSub=rows.length?'<b>'+fmtInt(reqN)+'</b> requested \u00b7 <b>'+fmtInt(ordN)+'</b> on order':'Request the first part for a job';
var html='<div class="wrap">';
html+=headerBlock(I.box,ctx.title||'Parts Requests',brief(['<b>'+fmtInt(rows.length)+'</b> parts requests','<b>'+fmtInt(ordN)+'</b> on order',costT>0?'<b>'+mnyC(costT)+'</b> in materials':'']),'New parts request');
html+='<div class="kpis">'+kpi('Requests',rows.length,heroSub,{hero:true,spark:spark(weekly(rows))})+kpi('On order',ordN,ordN>0?'Waiting on suppliers':reqN>0?'<b>'+fmtInt(reqN)+'</b> still to be ordered':'Nothing waiting on suppliers')+kpi('Materials cost',costT>0?mnyC(costT):'\u2014','Quantity \u00d7 unit cost across requests')+'</div>';
html+=sec('Parts pipeline')+'<div class="grid g21">'+panel('Requests by status',bd)+panel('Recent requests','<div class="rows">'+recent+'</div>')+'</div>';
html+='</div>';root.innerHTML=html;wire(root);
}
main();

customScreen.css:
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}.btn-primary:hover{filter:brightness(1.07);}
.btn-ghost{background:transparent;border:1px solid var(--fl-border);color:var(--fl-text);}.btn-ghost:hover{border-color:color-mix(in srgb,var(--fl-accent) 45%,transparent);}
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}.kpi-sub b{color:var(--fl-muted);font-weight:650;}
.kpi-spark{margin-top:auto;padding-top:10px;}.kpi-spark svg{display:block;width:100%;height:42px;}
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}
.grid{display:grid;gap:14px;align-items:start;}.g21{grid-template-columns:2fr 1fr;}.g12{grid-template-columns:1fr 2fr;}.g11{grid-template-columns:1fr 1fr;}.g111{grid-template-columns:1fr 1fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}.panel-link:hover{text-decoration:underline;}
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}.row:first-child{border-top:0;padding-top:2px;}.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 46px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}
.day{margin-top:14px;}.day:first-child{margin-top:0;}
.day-h{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-faint);padding-bottom:4px;}
.sch{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid var(--fl-border);}
.sch-t{flex:none;width:58px;font-size:12.5px;font-weight:700;color:var(--ax);font-variant-numeric:tabular-nums;}
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}.link-btn:hover{text-decoration:underline;}
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}
@media(max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21,.g12,.g11,.g111{grid-template-columns:1fr;}}
@media(max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 40px;}.title{font-size:21px;}}
.row-sub .pill{margin-left:6px;vertical-align:middle;}

customScreen.js:
var FL=window.FormLogic;
var RM=false;try{RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){}
function h(v){return FL.escapeHtml(v==null?'':String(v));}
function num(v){var x=parseFloat(v);return isNaN(x)?0:x;}
function fmtInt(v){return num(v).toLocaleString();}
function mny(v,c){return (c||'$')+num(v).toLocaleString(undefined,{maximumFractionDigits:0});}
function mnyC(v,c){var x=num(v);if(Math.abs(x)>=1000000)return (c||'$')+(x/1000000).toFixed(1).replace(/\.0$/,'')+'M';if(Math.abs(x)>=10000)return (c||'$')+Math.round(x/1000)+'k';return mny(x,c);}
function pd(s){if(!s)return null;var d=new Date(s);return isNaN(d.getTime())?null:d;}
function fmtDate(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric'}):'\u2014';}
function fmtDateY(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'\u2014';}
function sot(){var d=new Date();d.setHours(0,0,0,0);return d.getTime();}
function dayDiff(s){var d=pd(s);if(!d)return null;var x=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();return Math.round((x-sot())/86400000);}
function ago(s){var dd=dayDiff(s);if(dd==null)return '';if(dd===0)return 'today';if(dd<0)return (-dd)+'d ago';return 'in '+dd+'d';}
function fmtTime(s){if(!s)return '';var m=String(s).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(s);var hh=parseInt(m[1],10);var ap=hh>=12?'pm':'am';hh=hh%12;if(hh===0)hh=12;return hh+':'+m[2]+ap;}
function findForm(ctx,name){var t=String(name).toLowerCase();for(var i=0;i<ctx.forms.length;i++){if(String(ctx.forms[i].displayName||'').toLowerCase()===t)return ctx.forms[i];}return null;}
function optionMap(form,fieldId){var m={};if(!form||!form.fields)return m;for(var i=0;i<form.fields.length;i++){var f=form.fields[i];if(f.id===fieldId&&f.properties&&f.properties.options){var o=f.properties.options;for(var j=0;j<o.length;j++){m[o[j].value]=o[j].label;}}}return m;}
function labelFor(map,v){if(v==null||v==='')return '\u2014';return map[v]||String(v);}
async function recs(form,limit){if(!form)return [];try{return await FL.records(form.formId,{limit:limit||500});}catch(e){return [];}}
function nameMap(records,fn){var m={};for(var i=0;i<records.length;i++){var r=records[i];m[r.id]=fn(r.answers||{},r)||'';}return m;}
function refName(map,v){if(v==null||v==='')return '';if(Array.isArray(v))v=v[0];return map[v]||'';}
function countBy(records,fieldId){var c={};for(var i=0;i<records.length;i++){var v=(records[i].answers||{})[fieldId];if(Array.isArray(v)){for(var k=0;k<v.length;k++){if(v[k]!=null&&v[k]!=='')c[v[k]]=(c[v[k]]||0)+1;}}else if(v!=null&&v!==''){c[v]=(c[v]||0)+1;}}return c;}
function sumBy(records,fieldId){var t=0;for(var i=0;i<records.length;i++){t+=num((records[i].answers||{})[fieldId]);}return t;}
function weekly(records,weeks){weeks=weeks||8;var out=[];for(var i=0;i<weeks;i++)out.push(0);var now=Date.now();for(var r=0;r<records.length;r++){var d=pd(records[r].submittedAt);if(!d)continue;var wk=Math.floor((now-d.getTime())/604800000);if(wk>=0&&wk<weeks)out[weeks-1-wk]++;}return out;}
function icoSvg(d){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';}
var I={};
I.plus=icoSvg('<path d="M12 5v14M5 12h14"/>');
I.user=icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>');
I.users=icoSvg('<circle cx="9" cy="8.5" r="3.25"/><path d="M2.5 20c.6-3 3.2-4.5 6.5-4.5s5.9 1.5 6.5 4.5"/><path d="M15.5 5.6a3.25 3.25 0 0 1 0 5.8M17.6 15.9c2 .6 3.5 1.9 3.9 4.1"/>');
I.doc=icoSvg('<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>');
I.cal=icoSvg('<rect x="4" y="5" width="16" height="15.5" rx="2.5"/><path d="M8 3v4M16 3v4M4 10.5h16"/>');
I.clock=icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>');
I.chart=icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>');
I.check=icoSvg('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>');
I.alert=icoSvg('<path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4M12 16.8h.01"/>');
I.arrow=icoSvg('<path d="M5 12h14M13 6l6 6-6 6"/>');
I.money=icoSvg('<path d="M12 2.5v19"/><path d="M16.5 6H9.75a3.25 3.25 0 0 0 0 6.5h4.5a3.25 3.25 0 0 1 0 6.5H7"/>');
I.box=icoSvg('<path d="M21 8.2 12 3 3 8.2v7.6L12 21l9-5.2z"/><path d="M3.3 8.3 12 13.3l8.7-5M12 13.3V21"/>');
I.wrench=icoSvg('<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>');
I.shield=icoSvg('<path d="M12 3l7.5 2.8v5.4c0 4.3-3 7.7-7.5 9-4.5-1.3-7.5-4.7-7.5-9V5.8z"/>');
I.home=icoSvg('<path d="M4 11.5 12 4l8 7.5"/><path d="M6 10v10h12V10"/>');
I.tag=icoSvg('<path d="M3.5 11.3V4.5a1 1 0 0 1 1-1h6.8a1 1 0 0 1 .7.3l8.2 8.2a1.5 1.5 0 0 1 0 2.1l-6.1 6.1a1.5 1.5 0 0 1-2.1 0L3.8 12a1 1 0 0 1-.3-.7z"/><circle cx="8" cy="8" r="1.25"/>');
function spark(vals,w,hh){w=w||220;hh=hh||42;if(!vals||vals.length<2)return '';var mx=0,mn=Infinity;for(var i=0;i<vals.length;i++){if(vals[i]>mx)mx=vals[i];if(vals[i]<mn)mn=vals[i];}if(mx===0)return '';if(mn===mx)mn=0;var rng=mx-mn||1;var pts=[];for(var j=0;j<vals.length;j++){var x=2+(j/(vals.length-1))*(w-4);var y=(hh-5)-((vals[j]-mn)/rng)*(hh-12);pts.push(x.toFixed(1)+','+y.toFixed(1));}var line=pts.join(' ');return '<svg viewBox="0 0 '+w+' '+hh+'" preserveAspectRatio="none" aria-hidden="true"><polygon points="2,'+(hh-2)+' '+line+' '+(w-2)+','+(hh-2)+'" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/><polyline points="'+line+'" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function pill(text,kind){var c=kind==='good'?'var(--fl-good)':kind==='warn'?'var(--fl-warn)':kind==='bad'?'var(--fl-bad)':kind==='accent'?'var(--ax)':'var(--fl-muted)';var bg=(kind==='neutral'||!kind)?'var(--fl-track)':'color-mix(in srgb, '+c+' 15%, transparent)';return '<span class="pill" style="color:'+c+';background:'+bg+'">'+h(text)+'</span>';}
function kpi(label,val,sub,opts){opts=opts||{};var v=(typeof val==='number')?'<span data-count="'+val+'">'+fmtInt(val)+'</span>':val;return '<div class="kpi'+(opts.hero?' kpi-hero':'')+'"><div class="kpi-label">'+h(label)+'</div><div class="kpi-val">'+v+'</div>'+(sub?'<div class="kpi-sub">'+sub+'</div>':'')+(opts.spark?'<div class="kpi-spark">'+opts.spark+'</div>':'')+'</div>';}
function sec(label){return '<div class="sec">'+h(label)+'</div>';}
function panel(title,body,nav,navLabel){return '<div class="panel">'+(title?'<div class="panel-h"><div class="panel-t">'+h(title)+'</div>'+(nav?'<button class="panel-link" data-nav="'+h(nav)+'">'+h(navLabel||'View all')+'</button>':'')+'</div>':'')+body+'</div>';}
function barRow(label,count,max,color){var pct=max>0?Math.max(3,Math.round(count/max*100)):0;return '<div class="bar-row"><span class="bar-name" title="'+h(label)+'">'+h(label)+'</span><div class="bar-track"><div class="bar-fill" data-pct="'+pct+'" style="background:'+(color||'var(--fl-accent)')+'"></div></div><span class="bar-val">'+fmtInt(count)+'</span></div>';}
function breakdown(records,fieldId,map,opts){opts=opts||{};var counts=countBy(records,fieldId);var keys=Object.keys(map);for(var k in counts){if(keys.indexOf(k)===-1)keys.push(k);}var max=0,total=0;for(var i=0;i<keys.length;i++){var c=counts[keys[i]]||0;if(c>max)max=c;total+=c;}if(total===0)return '';keys.sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});var out='';for(var j=0;j<keys.length;j++){var n2=counts[keys[j]]||0;if(n2===0)continue;out+=barRow(labelFor(map,keys[j]),n2,max,opts.color);}return out;}
function rowItem(title,sub,right){return '<div class="row"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function qRow(color,title,sub,right){return '<div class="q-row" style="--q:'+color+'"><div class="row-main"><div class="row-title">'+title+'</div>'+(sub?'<div class="row-sub">'+sub+'</div>':'')+'</div>'+(right?'<div class="row-r">'+right+'</div>':'')+'</div>';}
function emptyBlock(ic,msg,nav,cta){return '<div class="empty">'+(ic||'')+h(msg)+(nav?'<div><button class="link-btn" data-nav="'+h(nav)+'">'+h(cta||'+ Add one')+'</button></div>':'')+'</div>';}
function acts(items){var out='<div class="acts">';for(var i=0;i<items.length;i++){var it=items[i];if(!it||!it.nav)continue;out+='<button class="act" data-nav="'+h(it.nav)+'">'+(it.icon||I.plus)+'<span>'+h(it.label)+'</span></button>';}out+='</div>';return out;}
function brief(clauses){var cs=[];for(var i=0;i<clauses.length;i++){if(clauses[i])cs.push(clauses[i]);}return cs.join('<span class="dot">\u00b7</span>');}
function headerBlock(glyph,titleText,briefHtml,ctas){var out='<div class="hdr"><div class="hdr-l"><div class="glyph">'+glyph+'</div><div style="min-width:0"><h1 class="title">'+h(titleText)+'</h1>'+(briefHtml?'<div class="brief">'+briefHtml+'</div>':'')+'</div></div>';if(ctas&&ctas.length){out+='<div class="hdr-r">';for(var i=0;i<ctas.length;i++){var c2=ctas[i];if(!c2||!c2.nav)continue;out+='<button class="btn '+(c2.ghost?'btn-ghost':'btn-primary')+'" data-nav="'+h(c2.nav)+'">'+(c2.icon||'')+'<span>'+h(c2.label)+'</span></button>';}out+='</div>';}out+='</div>';return out;}
function countUp(el){var target=parseFloat(el.getAttribute('data-count'));if(isNaN(target)||target<=0)return;var t0=null,dur=700;function step(ts){if(t0===null)t0=ts;var p=Math.min(1,(ts-t0)/dur);var e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e).toLocaleString();if(p<1)requestAnimationFrame(step);}requestAnimationFrame(step);}
function wire(root){var nav=root.querySelectorAll('[data-nav]');for(var i=0;i<nav.length;i++){(function(el){el.addEventListener('click',function(){var t=el.getAttribute('data-nav');if(t)FL.navigate(t);});})(nav[i]);}var kids=root.querySelectorAll('.wrap > *');for(var k2=0;k2<kids.length;k2++){kids[k2].classList.add('reveal');kids[k2].style.animationDelay=(Math.min(k2,8)*60)+'ms';}requestAnimationFrame(function(){requestAnimationFrame(function(){var f=root.querySelectorAll('.bar-fill');for(var j2=0;j2<f.length;j2++){f[j2].style.width=(f[j2].getAttribute('data-pct')||0)+'%';}});});if(!RM){var cs2=root.querySelectorAll('[data-count]');for(var m2=0;m2<cs2.length;m2++){countUp(cs2[m2]);}}}
function fatal(root,msg){root.innerHTML='<div class="wrap"><div class="load">'+h(msg)+'</div></div>';}
var iclip=icoSvg('<path d="M9 4H7a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-2"/><rect x="9" y="2.5" width="6" height="3" rx="1"/><path d="M9 12.5l2 2 4-4"/>');
function stKind(s){return s==='completed'||s==='invoiced'?'good':s==='on-hold'?'warn':s==='in-progress'?'accent':'neutral';}
function dayLabel(s){var d=pd(s);return d?d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}):'Upcoming';}
async function main(){
var root=document.getElementById('app');
var ctx;try{ctx=await FL.context();}catch(e){return fatal(root,'Could not load this dashboard.');}
var fCust=findForm(ctx,'Customers'),fJob=findForm(ctx,'Jobs'),fVisit=findForm(ctx,'Site Visits'),fInv=findForm(ctx,'Invoices'),fParts=findForm(ctx,'Parts Requests');
var d=await Promise.all([recs(fJob),recs(fCust),recs(fInv),recs(fParts)]);
var jobs=d[0],customers=d[1],invoices=d[2],parts=d[3];
var cMap=nameMap(customers,function(a){return a.name;});
var jbMap=nameMap(jobs,function(a){return refName(cMap,a.customer);});
var stMap=optionMap(fJob,'status'),tMap=optionMap(fJob,'job_type'),prMap=optionMap(fJob,'priority'),ivMap=optionMap(fInv,'status'),ppMap=optionMap(fParts,'status');
var stC=countBy(jobs,'status');
var openN=(stC['scheduled']||0)+(stC['in-progress']||0)+(stC['on-hold']||0);
var weekN=0,todayN=0,emergN=0;
for(var i=0;i<jobs.length;i++){var a=jobs[i].answers||{};var dd=dayDiff(a.scheduled_date);var op=a.status==='scheduled'||a.status==='in-progress'||a.status==='on-hold';if(dd!=null&&dd>=0&&dd<=7)weekN++;if(dd===0)todayN++;if(a.job_type==='emergency'&&op)emergN++;}
var outst=0,unpaidN=0,overdueN=0;
for(var i2=0;i2<invoices.length;i2++){var ia=invoices[i2].answers||{};if(ia.status==='sent'||ia.status==='overdue'){outst+=num(ia.total);unpaidN++;if(ia.status==='overdue')overdueN++;}}
var upcoming=[];
for(var u=0;u<jobs.length;u++){var ua=jobs[u].answers||{};var dd2=dayDiff(ua.scheduled_date);if(dd2!=null&&dd2>=0&&(ua.status==='scheduled'||ua.status==='in-progress'))upcoming.push(jobs[u]);}
upcoming.sort(function(x,y){return String((x.answers||{}).scheduled_date||'').localeCompare(String((y.answers||{}).scheduled_date||''));});
var grouped=upcoming.length>0;var board=grouped?upcoming.slice(0,8):jobs.slice(0,7);var boardTitle=grouped?'Today & upcoming':'Latest jobs';
var boardHtml='',lastKey='';
for(var b=0;b<board.length;b++){var ba=board[b].answers||{};var ttl=refName(cMap,ba.customer)||'Unassigned customer';var sub=h(labelFor(tMap,ba.job_type));if(ba.priority)sub+=pill(labelFor(prMap,ba.priority),ba.priority==='urgent'?'bad':ba.priority==='high'?'warn':'neutral');var right=(grouped?'':'<span class="chip">'+h(fmtDate(ba.scheduled_date||board[b].submittedAt))+'</span>')+pill(labelFor(stMap,ba.status),stKind(ba.status));if(grouped){var dd3=dayDiff(ba.scheduled_date);var key=dd3===0?'Today':dd3===1?'Tomorrow':dayLabel(ba.scheduled_date);if(key!==lastKey){if(lastKey!=='')boardHtml+='</div>';boardHtml+='<div class="day"><div class="day-h">'+h(key)+'</div>';lastKey=key;}boardHtml+='<div class="sch"><div class="row-main"><div class="row-title">'+h(ttl)+'</div><div class="row-sub">'+sub+'</div></div><div class="row-r">'+right+'</div></div>';}else{boardHtml+=rowItem(h(ttl),sub,right);}}
if(grouped&&lastKey!=='')boardHtml+='</div>';
if(!boardHtml)boardHtml=emptyBlock(I.wrench,'Booked jobs will appear here by day, ready to dispatch.',fJob?fJob.formId:'','+ New job');
var bd=breakdown(jobs,'status',stMap)||emptyBlock(I.chart,'The status breakdown appears once jobs are booked.',fJob?fJob.formId:'','+ New job');
var invHtml='';
for(var v2=0;v2<invoices.length&&v2<5;v2++){var ia2=invoices[v2].answers||{};var who=refName(cMap,ia2.customer)||refName(jbMap,ia2.job);var isub=(who?h(who)+' \u00b7 ':'')+h(fmtDate(ia2.issue_date));var ik=ia2.status==='paid'?'good':ia2.status==='overdue'?'bad':'neutral';invHtml+=rowItem(h(ia2.invoice_number||'Invoice'),isub,'<span class="amt">'+mny(ia2.total)+'</span>'+pill(labelFor(ivMap,ia2.status),ik));}
if(!invHtml)invHtml=emptyBlock(I.doc,'Raise an invoice from a completed job and it will land here.',fInv?fInv.formId:'','+ New invoice');
var onOrder=[];
for(var p0=0;p0<parts.length;p0++){var ps=(parts[p0].answers||{}).status;if(ps==='requested'||ps==='ordered')onOrder.push(parts[p0]);}
var ptHtml='';
for(var p2=0;p2<onOrder.length&&p2<5;p2++){var pa=onOrder[p2].answers||{};var psub=pa.supplier?h(pa.supplier):h(refName(jbMap,pa.job));ptHtml+=rowItem(h(pa.item||'Part'),psub,'<span class="chip">\u00d7 '+h(fmtInt(num(pa.quantity)||1))+'</span>'+pill(labelFor(ppMap,pa.status),pa.status==='ordered'?'accent':'neutral'));}
if(!ptHtml)ptHtml=emptyBlock(I.box,'Parts and materials requested for jobs will appear here.',fParts?fParts.formId:'','+ Request parts');
var html='<div class="wrap">';
html+=headerBlock(I.wrench,ctx.appName||'Field Service',brief(['<b>'+fmtInt(openN)+'</b> open jobs','<b>'+fmtInt(weekN)+'</b> booked this week','<b>'+fmtInt(emergN)+'</b> emergency','<b>'+mnyC(outst)+'</b> outstanding']),[{nav:fJob?fJob.formId:'',label:'New job',icon:I.plus},{nav:fCust?fCust.formId:'',label:'New customer',icon:I.user,ghost:true}]);
var heroSub=jobs.length?'<b>'+fmtInt(stC['scheduled']||0)+'</b> scheduled \u00b7 <b>'+fmtInt(stC['in-progress']||0)+'</b> in progress \u00b7 <b>'+fmtInt(stC['on-hold']||0)+'</b> on hold':'No jobs yet \u00b7 book your first job';
html+='<div class="kpis">'+kpi('Open jobs',jobs.length?openN:'\u2014',heroSub,{hero:true,spark:spark(weekly(jobs))})+kpi('This week',weekN,todayN>0?'<b>'+fmtInt(todayN)+'</b> on site today':'Booked over the next 7 days')+kpi('Emergency callouts',emergN,emergN>0?'<span style="color:var(--fl-bad);font-weight:650">Respond first</span>':'No emergency call-outs open')+kpi('Outstanding',mnyC(outst),overdueN>0?'<span style="color:var(--fl-bad);font-weight:650">'+fmtInt(overdueN)+' overdue</span>':(unpaidN>0?fmtInt(unpaidN)+' awaiting payment':'All invoices settled'))+'</div>';
html+=sec('Job board')+'<div class="grid g21">'+panel(boardTitle,boardHtml,fJob?'form/'+fJob.formId+'/responses':'')+panel('Jobs by status',bd,fJob?'form/'+fJob.formId+'/responses':'')+'</div>';
html+=sec('Money & materials')+'<div class="grid g11">'+panel('Invoices','<div class="rows">'+invHtml+'</div>',fInv?'form/'+fInv.formId+'/responses':'')+panel('Parts on order','<div class="rows">'+ptHtml+'</div>',fParts?'form/'+fParts.formId+'/responses':'')+'</div>';
html+=sec('Quick actions')+acts([{nav:fJob?fJob.formId:'',label:'New job',icon:I.wrench},{nav:fCust?fCust.formId:'',label:'New customer',icon:I.user},{nav:fVisit?fVisit.formId:'',label:'Log site visit',icon:iclip},{nav:fInv?fInv.formId:'',label:'New invoice',icon:I.doc},{nav:fParts?fParts.formId:'',label:'Request parts',icon:I.box}]);
html+='</div>';root.innerHTML=html;wire(root);
}
main();
